// The geometry of collisions and picking: sweeping a sphere along a line against spheres, triangles and boxes,
// rays against triangles and spheres, and the polygons of two meshes touching.

#include <math.h>
#include <stdint.h>

#include "collision_internal.hpp"

namespace bb::collision {
	// Box that is the mesh of the entity before it is moved. Boxes set with EntityBox are used when there is one.
	box3 local_bounds(entity const& e)
	{
		box3 box;
		if (e.has_box) {
			box.add({ e.box[0], e.box[1], e.box[2] });
			box.add({ e.box[0] + e.box[3], e.box[1] + e.box[4], e.box[2] + e.box[5] });
			return box;
		}
		for (uint32_t i = 0; i < e.surfaces.size; i++) {
			for (uint32_t v = 0; v < e.surfaces[i]->vertices.size; v++) {
				vertex3d const& vert = e.surfaces[i]->vertices[v];
				box.add({ vert.x, vert.y, vert.z });
			}
		}
		return box;
	}

	// Box that is around the entity in the world.
	box3 world_bounds(entity const& e, const float* m)
	{
		box3 local = local_bounds(e), result;
		if (local.empty) {
			return result;
		}
		for (int corner = 0; corner < 8; corner++) {
			result.add(transform(m, { (corner & 1) ? local.hi.x : local.lo.x, (corner & 2) ? local.hi.y : local.lo.y, (corner & 4) ? local.hi.z : local.lo.z }));
		}
		return result;
	}


	bool hit_update(hit_info& c, line3 const& line, float t, vec3 n)
	{
		if (t > c.time) {
			return false;
		}
		plane3 p = plane_through(at(line, t), n);
		if (dot(p.n, line.d) >= 0) {
			return false;
		}
		if (p.distance(line.o) < -collision_epsilon) {
			return false;
		}
		c.time   = t;
		c.normal = n;
		return true;
	}

	bool hit_sphere(hit_info& c, line3 const& line, float radius, vec3 dest, float dest_radius)
	{
		radius += dest_radius;
		line3 l = { line.o - dest, line.d };
		float a = dot(l.d, l.d);
		if (a == 0) {
			return false;
		}
		float b = dot(l.o, l.d) * 2;
		float cc = dot(l.o, l.o) - radius * radius;
		float d  = b * b - 4 * a * cc;
		if (d < 0) {
			return false;
		}
		float t1 = (-b + sqrtf(d)) / (2 * a), t2 = (-b - sqrtf(d)) / (2 * a);
		float t = t1 < t2 ? t1 : t2;
		if (t > c.time) {
			return false;
		}
		return hit_update(c, line, t, normalized(at(l, t)));
	}

	// v0, v1: the ends of the edge, pn: normal of the polygon, en: normal of the plane of the edge.
	bool hit_edge(hit_info& c, vec3 v0, vec3 v1, vec3 pn, vec3 en, line3 const& line, float radius)
	{
		vec3 axis_j = normalized(v1 - v0);
		// The matrix with en, the direction of the edge and pn as its columns, which turns what is in the world into
		// what is around the edge.
		auto to_edge   = [&](vec3 p) { return vec3{ dot(en, p), dot(axis_j, p), dot(pn, p) }; };
		auto from_edge = [&](vec3 p) { return en * p.x + axis_j * p.y + pn * p.z; };

		vec3  sv = to_edge(line.o - v0), dv = to_edge(line.o + line.d - v0);
		line3 l  = { sv, dv - sv };
		// The cylinder around the edge...
		float a = l.d.x * l.d.x + l.d.z * l.d.z;
		if (a == 0) {
			return false;
		}
		float b = (l.o.x * l.d.x + l.o.z * l.d.z) * 2;
		float cc = (l.o.x * l.o.x + l.o.z * l.o.z) - radius * radius;
		float d  = b * b - 4 * a * cc;
		if (d < 0) {
			return false;
		}
		float t1 = (-b + sqrtf(d)) / (2 * a), t2 = (-b - sqrtf(d)) / (2 * a);
		float t = t1 < t2 ? t1 : t2;
		if (t > c.time) {
			return false;
		}
		vec3 i = at(l, t), p;
		if (i.y > length(v1 - v0)) {
			return false; // Above the cylinder.
		}
		if (i.y >= 0) {
			p.y = i.y;
		} else {
			// ...and the sphere around the end of it.
			a = dot(l.d, l.d);
			if (a == 0) {
				return false;
			}
			b  = dot(l.o, l.d) * 2;
			cc = dot(l.o, l.o) - radius * radius;
			d  = b * b - 4 * a * cc;
			if (d < 0) {
				return false;
			}
			t1 = (-b + sqrtf(d)) / (2 * a);
			t2 = (-b - sqrtf(d)) / (2 * a);
			t  = t1 < t2 ? t1 : t2;
			if (t > c.time) {
				return false;
			}
			i = at(l, t);
		}
		return hit_update(c, line, t, normalized(from_edge(i - p)));
	}

	bool hit_triangle(hit_info& c, line3 const& line, float radius, vec3 v0, vec3 v1, vec3 v2)
	{
		plane3 p = plane_of(v0, v1, v2);
		if (dot(p.n, line.d) >= 0) {
			return false;
		}
		p.d -= radius; // The plane, moved out by the radius.
		float t = p.t_intersect(line);
		if (t > c.time) {
			return false;
		}
		plane3 p0 = plane_of(v0 + p.n, v1, v0), p1 = plane_of(v1 + p.n, v2, v1), p2 = plane_of(v2 + p.n, v0, v2);
		vec3   i = at(line, t);
		if ((p0.distance(i) >= 0) && (p1.distance(i) >= 0) && (p2.distance(i) >= 0)) {
			return hit_update(c, line, t, p.n);
		}
		if (radius <= 0) {
			return false;
		}
		bool hit = hit_edge(c, v0, v1, p.n, p0.n, line, radius);
		hit |= hit_edge(c, v1, v2, p.n, p1.n, line, radius);
		hit |= hit_edge(c, v2, v0, p.n, p2.n, line, radius);
		return hit;
	}

	bool hit_box(hit_info& c, line3 const& line, float radius, vec3 const* corners)
	{
		static const int quads[] = { 2, 3, 1, 0, 3, 7, 5, 1, 7, 6, 4, 5, 6, 2, 0, 4, 6, 7, 3, 2, 0, 1, 5, 4 };
		bool             hit     = false;
		for (int n = 0; n < 24; n += 4) {
			vec3   v0 = corners[quads[n]], v1 = corners[quads[n + 1]], v2 = corners[quads[n + 2]], v3 = corners[quads[n + 3]];
			plane3 p = plane_of(v0, v1, v2);
			if (dot(p.n, line.d) >= 0) {
				continue;
			}
			p.d -= radius;
			float t = p.t_intersect(line);
			if (t > c.time) {
				return false;
			}
			plane3 p0 = plane_of(v0 + p.n, v1, v0), p1 = plane_of(v1 + p.n, v2, v1), p2 = plane_of(v2 + p.n, v3, v2), p3 = plane_of(v3 + p.n, v0, v3);
			vec3   i = at(line, t);
			if ((p0.distance(i) >= 0) && (p1.distance(i) >= 0) && (p2.distance(i) >= 0) && (p3.distance(i) >= 0)) {
				hit |= hit_update(c, line, t, p.n);
				continue;
			}
			if (radius <= 0) {
				continue;
			}
			hit |= hit_edge(c, v0, v1, p.n, p0.n, line, radius);
			hit |= hit_edge(c, v1, v2, p.n, p1.n, line, radius);
			hit |= hit_edge(c, v2, v3, p.n, p2.n, line, radius);
			hit |= hit_edge(c, v3, v0, p.n, p3.n, line, radius);
		}
		return hit;
	}

	// The smallest root of a x^2 + b x + c that is less than the limit.
	bool lowest_root(float a, float b, float c, float limit, float& out)
	{
		float determinant = b * b - 4 * a * c;
		if ((determinant < 0) || (fabsf(a) < 1e-20f)) {
			return false;
		}
		float root = sqrtf(determinant);
		float r1 = (-b - root) / (2 * a), r2 = (-b + root) / (2 * a);
		if (r1 > r2) {
			float t = r1;
			r1      = r2;
			r2      = t;
		}
		if ((r1 > 0) && (r1 < limit)) {
			out = r1;
			return true;
		}
		if ((r2 > 0) && (r2 < limit)) {
			out = r2;
			return true;
		}
		return false;
	}

	// Ray against a triangle, with the length of the direction as the range. Returns the time in [0, 1].
	bool ray_triangle(vec3 origin, vec3 direction, vec3 a, vec3 b, vec3 c, float& t)
	{
		vec3  e1 = b - a, e2 = c - a, p = cross(direction, e2);
		float det = dot(e1, p);
		if (fabsf(det) < 1e-12f) {
			return false;
		}
		float inverse = 1.0f / det;
		vec3  from    = origin - a;
		float u       = dot(from, p) * inverse;
		if ((u < 0) || (u > 1)) {
			return false;
		}
		vec3  q = cross(from, e1);
		float v = dot(direction, q) * inverse;
		if ((v < 0) || (u + v > 1)) {
			return false;
		}
		t = dot(e2, q) * inverse;
		return (t >= 0) && (t <= 1);
	}

	// Ray (or sphere with a radius) against a sphere. Time in [0, 1].
	bool ray_sphere(vec3 origin, vec3 direction, vec3 center, float radius, float& t)
	{
		vec3  d = origin - center;
		float a = dot(direction, direction), b = 2 * dot(direction, d), c = dot(d, d) - radius * radius, root;
		if (c <= 0) {
			t = 0;
			return true;
		}
		if (!lowest_root(a, b, c, 1.0f + 1e-6f, root)) {
			return false;
		}
		t = root;
		return true;
	}

} // namespace bb::collision

using namespace bb::collision;

extern "C" {
// Do the polygons of the two meshes touch?
int32_t bb_meshes_intersect(int32_t first, int32_t second)
{
	entity *a = need(first, "MeshesIntersect"), *b = need(second, "MeshesIntersect");
	float   ma[16], mb[16];
	world_matrix(first, ma);
	world_matrix(second, mb);
	box3 wa = world_bounds(*a, ma), wb = world_bounds(*b, mb);
	if (!wa.overlaps(wb)) {
		return 0;
	}
	box3 overlap;
	overlap.add({ fmaxf(wa.lo.x, wb.lo.x), fmaxf(wa.lo.y, wb.lo.y), fmaxf(wa.lo.z, wb.lo.z) });
	overlap.add({ fminf(wa.hi.x, wb.hi.x), fminf(wa.hi.y, wb.hi.y), fminf(wa.hi.z, wb.hi.z) });

	// Triangles of the second mesh that are in the overlap, tested against the edges of the first mesh's, and back.
	buffer<triangle> from_b;
	each_triangle(second, *b, overlap, [&](triangle const& t) { from_b.push(t); });
	bool hit = false;
	each_triangle(first, *a, overlap, [&](triangle const& t) {
		if (hit) {
			return;
		}
		vec3 edges[3][2] = { { t.a, t.b }, { t.b, t.c }, { t.c, t.a } };
		for (uint32_t i = 0; i < from_b.size && !hit; i++) {
			triangle const& u = from_b[i];
			float           time;
			for (auto& edge : edges) {
				if (ray_triangle(edge[0], edge[1] - edge[0], u.a, u.b, u.c, time)) {
					hit = true;
					return;
				}
			}
			vec3 other_edges[3][2] = { { u.a, u.b }, { u.b, u.c }, { u.c, u.a } };
			for (auto& edge : other_edges) {
				if (ray_triangle(edge[0], edge[1] - edge[0], t.a, t.b, t.c, time)) {
					hit = true;
					return;
				}
			}
		}
	});
	from_b.release();
	return hit ? 1 : 0;
}
}
